import{_ as s,l as i,o as e,c as n,v as t,p as d,x as r,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"时间戳排序","description":"","frontmatter":{"title":"时间戳排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timestamp-ordering.md","filePath":"cs/timestamp-ordering.md","lastUpdated":1789023840000}'),m={name:"cs/timestamp-ordering.md"};function _(h,a,T,C,E,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="时间戳排序" tabindex="-1">时间戳排序 <a class="header-anchor" href="#时间戳排序" aria-label="Permalink to &quot;时间戳排序&quot;">​</a></h1><div class="epigraph"><p>每事务一个时间戳，读写按戳排序：晚读早写的数据则拒绝或等待。调度在时间轴上，不必两阶段锁点。</p><footer>—— 据 Bernstein and Goodman 时间戳并发；Reed；Gray and Reuter；主干 2PL 对照</footer></div><p>存储对照在<a href="/cs/index-organized-table">索引组织表</a>封口。本课打开并发控制续：主干 <a href="/cs/two-pl">2PL</a> 与 <a href="/cs/mvcc">MVCC</a> 已给锁与版本。缺口是时间戳排序（TSO）：事务 \\(T\\) 带 \\(ts(T)\\)，对象上维护读/写戳，冲突按戳序解决，实现可串行的一种。OCC 下一课更乐观。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PL 阻塞；死锁要检测。TSO：若 \\(T\\) 写对象 \\(X\\)，但 \\(X\\) 已被更晚事务读或写，则 \\(T\\) 太晚，abort 并 vis 新戳重来（或 wait 变种）。Thomas 写规则：过时写可忽略而不 abort。缺口是<strong>无锁点仍要拒绝乱序</strong>，不是取消隔离。</p><p>多版本时间戳：写创建版本 \\(ts\\)，读取不超过自己戳的最近版——与 MVCC 合流。单版本 TSO 对读写冲突更苛刻。基本 vs 严格：是否等写者提交才让读者看见，对应脏读。</p><p><span class="marginnote">Bernstein, Hadzilacos, Goodman 教材。时间戳可由计数器或 TrueTime 后课一类时钟给。本课单机逻辑戳。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象元数据：<code>max_read_ts</code>、<code>max_write_ts</code>（及版本链）。读：若 \\(ts(T) \\lt max_write_ts\\) 可能 abort 或读旧版。写：若 \\(ts(T) \\lt max_read_ts\\) abort（已有更晚读）。提交：刷日志仍 WAL。</p><p>与快照隔离：SI 用开始戳读，提交戳写检测，不是完整 TSO。本课 TSO 更接近「调度等价于戳序串行」。</p>',10)),(e(),d(c,null,{default:r(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BA%8B%E5%8A%A1%20ts%22%5D%20--%3E%20R%5B%22%E8%AF%BB%3A%20%E9%80%89%E4%B8%8D%E8%B6%85%E8%BF%87%20ts%20%E7%9A%84%E7%89%88%E6%9C%AC%22%5D%0A%20%20T%20--%3E%20W%5B%22%E5%86%99%3A%20%E8%8B%A5%E5%B7%B2%E6%9C%89%E6%9B%B4%E6%99%9A%E8%AF%BB%E5%88%99%20abort%22%5D%0A%20%20W%20--%3E%20C%5B%22%E6%8F%90%E4%BA%A4%E6%8C%89%20WAL%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重启：时间戳必须单调，不能回卷导致旧事务变「未来」。时钟回拨是分布式课。长事务拿极早戳会与后续写大量冲突——和 MVCC 老快照挡 GC 对偶：这里是活锁/重试。</p><p>锁与 TSO 混合存在于产品，本课纯机制。死锁少（更多 abort），重启风暴是代价。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 OCC 的读集验证。也不把 TSO 当网络协议。间隙幻读：谓词读写仍要谓词戳或间隙结构，后课。</p><p>后课默认：可用时间戳接受/拒绝代替 2PL 阻塞。OCC：先无锁读写工作副本，提交时验证。</p><p>戳序是可串行的充分实现之一，不是用户看见的隔离级别名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TSO 用对象上的读写戳拒绝乱序访问。</li><li>多版本变体与 MVCC 合流；过时写可 Thomas 忽略。</li><li>OCC 下一课：验证在提交点。</li><li>出处：Bernstein and Goodman；Reed；Gray and Reuter。</li></ul>',9))])}const f=s(m,[["render",_]]);export{B as __pageData,f as default};
